#include "service_adapters.hpp"
namespace exotic::runtime {
CallbackService::CallbackService(std::string n,std::vector<std::string>d,Fn r,Fn s,Fn st,Fn j,Health h):name_(std::move(n)),deps_(std::move(d)),recover_(std::move(r)),start_(std::move(s)),stop_(std::move(st)),join_(std::move(j)),health_(std::move(h)){}std::string CallbackService::name()const{return name_;}std::vector<std::string>CallbackService::dependencies()const{return deps_;}void CallbackService::recover(){if(recover_)recover_();}void CallbackService::start(){if(start_)start_();}void CallbackService::request_stop(){if(stop_)stop_();}void CallbackService::join(){if(join_)join_();}ServiceHealth CallbackService::health(){return health_?health_():ServiceHealth{name_,ServiceState::Running,HealthLevel::Healthy,"callback service healthy",{},Clock::now()};}
SchedulerService::SchedulerService(autonomy::scheduler::DurableScheduler&s,std::size_t w,std::string p):s_(s),workers_(w),prefix_(std::move(p)){}void SchedulerService::recover(){s_.recover();}void SchedulerService::start(){s_.start(workers_,prefix_);running_=true;}void SchedulerService::request_stop(){s_.request_stop();}void SchedulerService::join(){s_.join();running_=false;}ServiceHealth SchedulerService::health(){auto st=s_.stats();ServiceHealth h;h.service=name();h.state=running_?ServiceState::Running:ServiceState::Stopped;h.level=running_?HealthLevel::Healthy:HealthLevel::Unknown;h.message="running="+std::to_string(st.running)+", pending="+std::to_string(st.pending)+", dead_lettered="+std::to_string(st.dead_lettered);h.measurements={{"pending",double(st.pending)},{"running",double(st.running)},{"dead_lettered",double(st.dead_lettered)},{"active_leases",double(st.active_leases)}};return h;}
GovernanceService::GovernanceService(autonomy::governance::GovernanceService&s,autonomy::governance::GovernanceRepository&r):service_(s),repo_(r){}void GovernanceService::recover(){service_.expire_requests(Clock::now());}void GovernanceService::start(){running_=true;}void GovernanceService::request_stop(){running_=false;}void GovernanceService::join(){}ServiceHealth GovernanceService::health(){auto stopped=repo_.emergency_stop_active();auto pending=repo_.load_pending(Clock::now()).size();return{name(),running_?ServiceState::Running:ServiceState::Stopped,stopped?HealthLevel::Degraded:HealthLevel::Healthy,stopped?"emergency stop active":"pending approvals="+std::to_string(pending),{{"pending_approvals",double(pending)}},Clock::now()};}
ResourceService::ResourceService(autonomy::resources::ResourceGovernor&g,autonomy::resources::ResourceRecoveryManager&r):governor_(g),recovery_(r){}void ResourceService::recover(){recovered_=recovery_.recover().expired_released;}void ResourceService::start(){running_=true;}void ResourceService::request_stop(){running_=false;}void ResourceService::join(){}ServiceHealth ResourceService::health(){auto s=governor_.status();auto level=s.emergency_stop?HealthLevel::Degraded:(s.open_circuits?HealthLevel::Degraded:HealthLevel::Healthy);return{name(),running_?ServiceState::Running:ServiceState::Stopped,level,s.emergency_stop?"resource emergency stop active":"active reservations="+std::to_string(s.active_reservations),{{"accounts",double(s.accounts)},{"active_reservations",double(s.active_reservations)},{"open_circuits",double(s.open_circuits)},{"anomalies",double(s.anomalies)},{"recovered_reservations",double(recovered_)}},Clock::now()};}
AgentService::AgentService(autonomy::agents::AgentRegistry&r,autonomy::agents::AgentRecoveryManager&rec):registry_(r),recovery_(rec){}void AgentService::recover(){auto x=recovery_.recover();recovered_=x.interrupted_assignments+x.released_bindings;}void AgentService::start(){running_=true;}void AgentService::request_stop(){running_=false;}void AgentService::join(){}ServiceHealth AgentService::health(){auto s=registry_.repository().status(Clock::now()-std::chrono::seconds(30));auto level=s.unhealthy?HealthLevel::Degraded:HealthLevel::Healthy;return{name(),running_?ServiceState::Running:ServiceState::Stopped,level,"active="+std::to_string(s.active)+", available="+std::to_string(s.available),{{"registered",double(s.registered)},{"active",double(s.active)},{"available",double(s.available)},{"unhealthy",double(s.unhealthy)},{"running_assignments",double(s.running_assignments)},{"stale_bindings",double(s.stale_bindings)},{"recovered",double(recovered_)}},Clock::now()};}
AgentHeartbeatService::AgentHeartbeatService(autonomy::agents::AgentRegistry&r,autonomy::agents::AgentId id,std::chrono::milliseconds i):registry_(r),id_(id),interval_(i){}void AgentHeartbeatService::start(){running_=true;thread_=std::jthread([this](std::stop_token stop){while(!stop.stop_requested()){auto a=registry_.load(id_);if(a)registry_.heartbeat(id_,autonomy::agents::HealthState::Healthy,a->availability,a->workload);std::this_thread::sleep_for(interval_);}});}void AgentHeartbeatService::request_stop(){thread_.request_stop();}void AgentHeartbeatService::join(){if(thread_.joinable())thread_.join();running_=false;}ServiceHealth AgentHeartbeatService::health(){return{name(),running_?ServiceState::Running:ServiceState::Stopped,running_?HealthLevel::Healthy:HealthLevel::Unknown,"local agent heartbeat",{},Clock::now()};}
}
